#!/usr/bin/env python3
"""
generate_template.py
=====================
Single-file project automation for the Flutter ERP/POS template.

Generates, in one pass:
  1. The COMPLETE `core/` layer — constants, network, session, storage,
     observers, di, theme, utils — AND the full `core/widgets/{common,utility}`
     widget library (this merges what used to be `generate_core_widget.py`),
     including a handful of widgets that exist in the real project but were
     missing from that generator: `exit_app_alert.dart`, `shimmer_extension.dart`,
     a `common/custom_network_image.dart`, and a `utility/custom_filter_bar.dart`.
  2. `routes/` (route_names.dart, app_router.dart, app_initialization.dart),
     scoped to the features this script actually generates.
  3. Exactly these 13 features, each with the FULL feature-first shape:
         data/models, data/repositories,
         presentation/states, presentation/controllers,
         presentation/screens (_screen / _mobile_view / _tab_view),
         presentation/widgets
     -> onboarding, login, forgot_password, reset_password, register,
        otp_verification, change_password, main_shell, notifications,
        profile, edit_profile, settings, system

No other features (home, activity, search, cart, orders, products,
analytics, audit_log, terms_privacy, help_support...) are generated by this
script — add them later with `generate_module.py` / `add_api_feature.py`.

IMPORTANT ADAPTATIONS (since only 13 features are in scope here):
  - `main_shell` only wires bottom-nav tabs to features that exist in this
    scope: Notifications, Profile, Settings (not Home/Activity/Orders/
    Analytics, which aren't generated here).
  - `system`'s NotFoundScreen points "Back to Home" at RouteNames.mainShell
    instead of a `home` route, since `home` isn't generated here.
  - `profile` / `settings` don't wire navigation to Terms & Privacy or
    Help & Support (not generated here) — those tiles are left as
    `// TODO` callbacks, same convention used everywhere else in this
    template for not-yet-wired actions.
  - Every feature gets a `presentation/states/<feature>_state.dart` file
    (even a minimal one) so `add_api_feature.py` can patch it later. The
    two exceptions are `main_shell` (its state is a plain `int` tab index)
    and `system` (a 4-unrelated-screens utility bucket) — both documented
    inline where relevant.

Usage:
    python generate_template.py                   # write only missing files
    python generate_template.py --overwrite        # replace existing files too
    python generate_template.py --dry-run          # preview, write nothing
    python generate_template.py --format           # run `dart format` after
    python generate_template.py --skip-pub-add      # don't auto `flutter pub add`
    python generate_template.py --package my_app    # override package name
    python generate_template.py --root /path/proj   # generate into another project
"""
from __future__ import annotations

import argparse
import re
import subprocess
import sys
from pathlib import Path
from textwrap import dedent


def dart(source: str) -> str:
    return dedent(source).strip() + "\n"


DEFAULT_PACKAGE_NAME = "template_test"

# =====================================================================
# CORE WIDGET LIBRARY  (merged from generate_core_widget.py, plus the
# handful of widgets that exist in the real project but were missing
# from that generator — see module docstring)
# =====================================================================

