# =====================================================================
# GENERIC FILE-WRITING HELPERS
# =====================================================================

def render(content: str, package_name: str) -> str:
    return content.replace("__PACKAGE_NAME__", package_name)


def write_file(path: Path, content: str, overwrite: bool, dry_run: bool) -> str:
    if path.exists() and not overwrite:
        return "skipped"
    if not dry_run:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")
    return "written"


def write_many(base_dir: Path, files: dict[str, str], package_name: str,
                overwrite: bool, dry_run: bool, counts: dict[str, int]) -> None:
    for rel_path, content in files.items():
        result = write_file(base_dir / rel_path, render(content, package_name), overwrite, dry_run)
        counts[result] = counts.get(result, 0) + 1
        print(f"{result:>7}: {base_dir / rel_path}")


def write_barrel_file(widgets_dir: Path, common: dict, utility: dict,
                       overwrite: bool, dry_run: bool, counts: dict[str, int]) -> None:
    exports = [
        *[f"export 'common/{name}';" for name in sorted(common)],
        *[f"export 'utility/{name}';" for name in sorted(utility)],
    ]
    content = "// Generated core widget exports.\n" + "\n".join(exports) + "\n"
    result = write_file(widgets_dir / "core_widgets.dart", content, overwrite, dry_run)
    counts[result] = counts.get(result, 0) + 1
    print(f"{result:>7}: {widgets_dir / 'core_widgets.dart'}")


def run_dart_format(root: Path) -> None:
    result = subprocess.run(["dart", "format", "lib"], cwd=root, text=True)
    if result.returncode != 0:
        raise RuntimeError("dart format failed")


def package_name_from_pubspec(pubspec: Path, fallback: str) -> str:
    if not pubspec.exists():
        return fallback
    match = re.search(r"^name:\s*([a-zA-Z0-9_]+)\s*$", pubspec.read_text(encoding="utf-8"), re.MULTILINE)
    return match.group(1) if match else fallback


