# =====================================================================
# VALIDATION
# =====================================================================

def validate_pubspec(root: Path) -> None:
    pubspec = root / "pubspec.yaml"
    if not pubspec.exists():
        print(
            f"\n⚠️  No pubspec.yaml found at {pubspec}\n"
            "   This isn't a Flutter project root yet. Run:\n"
            "     flutter create --platforms=android,ios .\n"
            "   then re-run this script.",
            file=sys.stderr,
        )


# =====================================================================
# PUB DEPENDENCIES — every package actually imported by the generated
# code above. Add more here if you extend the templates with new
# imports (shared_preferences, google_fonts, fl_chart, intl...).
# =====================================================================

PUB_DEPENDENCIES = [
    "flutter_riverpod",
    "go_router",
    "dio",
    "flutter_svg",
    "cached_network_image",
    "flutter_secure_storage",
    "hive",
    "hive_flutter",
    "connectivity_plus",
    "skeletonizer",
]


def run_pub_add(root: Path, skip: bool) -> None:
    if skip:
        print("⏭  Skipping 'flutter pub add' (--skip-pub-add passed).")
        return
    if not (root / "pubspec.yaml").exists():
        print(f"⚠️  No pubspec.yaml — add dependencies manually:\n     flutter pub add {' '.join(PUB_DEPENDENCIES)}")
        return

    print(f"\n📦 Running: flutter pub add {' '.join(PUB_DEPENDENCIES)}")
    try:
        result = subprocess.run(["flutter", "pub", "add", *PUB_DEPENDENCIES], cwd=root, capture_output=True, text=True)
        print(result.stdout)
        if result.returncode != 0:
            print(result.stderr)
            print(f"⚠️  'flutter pub add' failed. Add manually:\n     flutter pub add {' '.join(PUB_DEPENDENCIES)}")
        else:
            print("✅ Dependencies added to pubspec.yaml.")
    except FileNotFoundError:
        print(f"⚠️  'flutter' not found on PATH. Add manually:\n     flutter pub add {' '.join(PUB_DEPENDENCIES)}")


# =====================================================================
# ORCHESTRATION
# =====================================================================

def main() -> int:
    parser = argparse.ArgumentParser(description="Generate the complete Flutter ERP/POS template (core + widgets + 13 features).")
    parser.add_argument("--root", default=".", help="Flutter project root (default: current directory)")
    parser.add_argument("--package", default=None, help="Override the package name (default: read from pubspec.yaml, else 'template_test')")
    parser.add_argument("--overwrite", "-o", action="store_true", help="Overwrite existing files")
    parser.add_argument("--dry-run", action="store_true", help="Show what would be generated without writing")
    parser.add_argument("--format", action="store_true", help="Run `dart format lib` after generation")
    parser.add_argument("--skip-pub-add", action="store_true", help="Don't auto-run `flutter pub add`")
    parser.add_argument("--skip-main", action="store_true", help="Don't (re)write lib/main.dart")
    args = parser.parse_args()

    root = Path(args.root).resolve()
    lib_path = root / "lib"

    validate_pubspec(root)
    package_name = args.package or package_name_from_pubspec(root / "pubspec.yaml", DEFAULT_PACKAGE_NAME)
    print(f"📦 Package name: {package_name}")

    counts: dict[str, int] = {}

    print("\n== Core widgets (common/) ==")
    write_many(lib_path / "core" / "widgets" / "common", COMMON_WIDGETS, package_name, args.overwrite, args.dry_run, counts)

    print("\n== Core widgets (utility/) ==")
    write_many(lib_path / "core" / "widgets" / "utility", UTILITY_WIDGETS, package_name, args.overwrite, args.dry_run, counts)

    print("\n== Core widgets barrel export ==")
    write_barrel_file(lib_path / "core" / "widgets", COMMON_WIDGETS, UTILITY_WIDGETS, args.overwrite, args.dry_run, counts)

    print("\n== Core (constants/network/session/storage/observers/di/theme/utils) ==")
    write_many(lib_path / "core", CORE_FILES, package_name, args.overwrite, args.dry_run, counts)

    print("\n== Routes ==")
    write_many(lib_path / "routes", ROUTE_FILES, package_name, args.overwrite, args.dry_run, counts)

    print("\n== Features ==")
    for feature_name, files in FEATURES.items():
        print(f"\n  -- {feature_name} --")
        write_many(lib_path / "features" / feature_name, files, package_name, args.overwrite, args.dry_run, counts)

    if not args.skip_main:
        print("\n== main.dart ==")
        result = write_file(lib_path / "main.dart", render(MAIN_DART_TEMPLATE, package_name), args.overwrite, args.dry_run)
        counts[result] = counts.get(result, 0) + 1
        print(f"{result:>7}: {lib_path / 'main.dart'}")

    if args.format and not args.dry_run:
        try:
            run_dart_format(root)
        except (FileNotFoundError, RuntimeError) as error:
            print(f"Formatting failed: {error}", file=sys.stderr)

    run_pub_add(root, args.skip_pub_add)

    print(f"\n🎉 Done. Written: {counts.get('written', 0)} | Skipped (already existed): {counts.get('skipped', 0)}")
    print("Features generated: " + ", ".join(FEATURES.keys()))
    print("\nNext steps:")
    print("  1. flutter pub get")
    print("  2. Drop matching SVGs into assets/clip/ (404.svg, maintenance.svg, warning.svg, wifi.svg) referenced by core/constants/app_assets.dart")
    print("  3. flutter run")
    print("  4. Add more features later with generate_module.py, then wire real endpoints with add_api_feature.py")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())